(() => {
'use strict';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d',{alpha:false});
const W=960,H=540,ground=442,netX=480,netTop=238;
let view={w:W,h:H,scale:1,ox:0,oy:0};
function resize(){const dpr=Math.min(devicePixelRatio||1,2),w=innerWidth,h=innerHeight;canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);view.scale=Math.min(w/W,h/H);view.ox=(w-W*view.scale)/2;view.oy=(h-H*view.scale)/2;ctx.setTransform(dpr*view.scale,0,0,dpr*view.scale,dpr*view.ox,dpr*view.oy);}
addEventListener('resize',resize);resize();
const $=s=>document.querySelector(s),menu=$('#menu'),hud=$('#hud'),modal=$('#modal'),result=$('#result');
const saveKey='pixelVolleySaveV1';
const defaultSave={name:'ROOKIE',level:1,xp:0,coins:120,club:'VOLT CITY',wins:0,losses:0,skill:[1,1,1,1,1],gear:0,played:false};
let profile;try{profile={...defaultSave,...JSON.parse(localStorage.getItem(saveKey)||'{}')}}catch{profile={...defaultSave}}
function persist(){localStorage.setItem(saveKey,JSON.stringify(profile));$('#menuProfile').textContent=`${profile.name.toUpperCase()} • LV ${profile.level}`;}
persist();
const colors={bg:'#111827',court:'#d7ab72',lime:'#d8ff64',teal:'#44d4cc',red:'#f3748a'};
let scene='menu',mode='quick',lastTime=0,elapsed=0,points=[0,0],serving=0,ball,players=[],sparks=[],crowd=[],state='serve',stateTimer=0,paused=false,matchEnded=false,skill=100,skillCooldown=0,serveType=0,playerAnim=0,trainingTouches=0,abilityName='POWER',nameSound=true;
const keys={};
function initCrowd(){crowd=[];for(let i=0;i<80;i++)crowd.push({x:i*13,y:111+Math.random()*54,c:Math.random()>.5?'#eb8a9b':'#6dcad2',phase:Math.random()*7});}initCrowd();
function person(team,index,x,y){const stats=team===0?{speed:2.55+jit(.1),jump:1,hit:1,receive:1,control:1}:{speed:1.75+jit(.45),jump:.86,hit:.82,receive:.82,control:.8};return{x,y,vx:0,vy:0,team,index,w:25,h:50,onGround:true,jumpTime:0,pose:'idle',anim:Math.random()*9,stats,cool:0,glow:0};}
function jit(a){return(Math.random()-.5)*a}
function resetTeams(){players=[];const teamPos=[[365,415],[290,415],[205,415]],cpuPos=[[595,415],[670,415],[745,415]];for(let i=0;i<3;i++){players.push(person(0,i,...teamPos[i]),person(1,i,...cpuPos[i]));}players[0].isUser=true;}
function newBall(){ball={x:serving===0?348:612,y:serving===0?330:330,vx:0,vy:0,r:9,spin:0,trail:[],lastTouch:-1,bounces:0};}
function startGame(which='quick') {mode=which;scene='game';paused=false;matchEnded=false;points=[0,0];serving=Math.random()<.5?0:1;elapsed=0;skill=100;trainingTouches=0;abilityName=['POWER','QUICK JUMP','IRON WALL','PERFECT','ACE SERVE'][profile.skill.indexOf(Math.max(...profile.skill))]||'POWER';resetTeams();newBall();state='serve';stateTimer=0;menu.classList.add('hidden');modal.classList.add('hidden');result.classList.add('hidden');hud.classList.remove('hidden');$('#touchTip').textContent=serving===0?'TAP SERVE TO START THE RALLY':'CPU IS SERVING — GET READY';updateHud();if(mode==='training')$('#callout').textContent='TRAINING • PRACTICE SERVE, RECEIVE, SET & SPIKE';else $('#callout').textContent='FIRST TO 15 • WIN BY 2';}
function backMenu(){scene='menu';paused=false;hud.classList.add('hidden');result.classList.add('hidden');menu.classList.remove('hidden');modal.classList.add('hidden');persist();}
function updateHud(){ $('#homeScore').textContent=String(points[0]).padStart(2,'0');$('#awayScore').textContent=String(points[1]).padStart(2,'0');$('#rallyStatus').textContent=state==='serve'?'SERVE':state==='dead'?'POINT':state==='pause'?'PAUSED':'RALLY';$('#gameClock').textContent=`${String(Math.floor(elapsed/60)).padStart(2,'0')}:${String(Math.floor(elapsed%60)).padStart(2,'0')}`;$('#skillFill').style.width=`${skill}%`;$('#skillName').textContent=abilityName;}
function score(pointTeam,reason='POINT!'){if(mode==='training'){state='dead';stateTimer=1;$('#callout').textContent=`${reason} • PRACTICE RALLY ${++trainingTouches}`;serving=0;return;}points[pointTeam]++;profile.xp+=pointTeam===0?30:8;profile.coins+=pointTeam===0?12:3;const won=points[pointTeam]>=15&&points[pointTeam]-points[1-pointTeam]>=2;if(won){finishMatch(pointTeam===0);return;}serving=pointTeam;state='dead';stateTimer=1.5;$('#callout').textContent=`${pointTeam===0?'YOUR POINT':'CPU POINT'} • ${reason}`;updateHud();persist();}
function finishMatch(win){matchEnded=true;state='dead';if(win){profile.wins++;profile.xp+=120;profile.coins+=100;$('#callout').textContent='MATCH WON! +100 COINS';}else{profile.losses++;$('#callout').textContent='MATCH OVER • NEXT TIME';}if(mode==='tournament'&&win){profile.coins+=150;profile.xp+=100;}awardXP();persist();setTimeout(()=>showResult(win),750);}
function awardXP(){while(profile.xp>=profile.level*220){profile.xp-=profile.level*220;profile.level++;profile.coins+=50;}}
function showResult(win){result.innerHTML=`<div class="result-panel"><div class="modal-eyebrow">${mode==='tournament'?'NEON CUP • ROUND 1':'PIXEL SPORTS LEAGUE'}</div><h2 style="color:${win?'var(--lime)':'#ff8297'}">${win?'VICTORY!':'MATCH OVER'}</h2><div class="result-score">${String(points[0]).padStart(2,'0')} — ${String(points[1]).padStart(2,'0')}</div><p>${win?'A brilliant performance.':'Every loss is a lesson. Run it back.'}<br>+${win?(mode==='tournament'?250:100):3} coins earned</p><div class="modal-actions" style="justify-content:center"><button class="primary-action" id="againBtn">PLAY AGAIN</button><button id="resultMenu">MAIN MENU</button></div></div>`;result.classList.remove('hidden');$('#againBtn').onclick=()=>startGame(mode);$('#resultMenu').onclick=backMenu;}
function act(type){if(scene!=='game'||paused||matchEnded)return;const user=players[0];if(type==='jump'){if(user.onGround){user.vy=-8.8*user.stats.jump*(skill>=100&&abilityName==='QUICK JUMP'?1.35:1);user.onGround=false;user.pose='jump';user.jumpTime=0;}return;}if(type==='serve'){if(state==='serve'&&serving===0){serveType=(serveType+1)%3;serveBall();}return;}if(state==='serve')return;user.pose=type==='pass'?'receive':type==='set'?'set':'hit';user.cool=.28;user.glow=.2;
 const dx=ball.x-user.x,dy=(user.y-18)-ball.y,dist=Math.hypot(dx,dy);let range=type==='hit'?83:type==='set'?65:70;if(!user.onGround)range+=13;if(dist<range&&ball.lastTouch!==0){if(type==='pass'){contact(user,'pass');}else if(type==='set'){contact(user,'set');}else if(type==='hit'){contact(user,'hit');}}
}
function serveBall(){const user=players[0];state='rally';user.pose='serve';ball.x=user.x+20;ball.y=user.y-45;const power=serveType===1?10:serveType===2?9.3:8.6;ball.vx=power;ball.vy=serveType===2?-6.5:serveType===1?-2.5:-4.8;ball.spin=serveType===1?-.06:serveType===2?.1:0;ball.lastTouch=0;ball.trail=[];$('#callout').textContent=['POWER SERVE!','FLOAT SERVE!','JUMP SERVE!'][serveType];skill=Math.max(0,skill-18);updateHud();}
function contact(p,type){if(ball.lastTouch===p.team&&type!=='hit')return;let perfect=Math.random()<p.stats.control*.7+(profile.skill[3]*.04);if(type==='pass'){ball.vx=(p.team===0?1:-1)*(2.1+jit(1.2));ball.vy=-7.8-(perfect?1.2:0);ball.x+=p.team===0?10:-10;ball.lastTouch=p.team;p.pose='receive';$('#callout').textContent=perfect?'CLEAN DIG!':'RECEIVED';skill=Math.min(100,skill+18);}
 else if(type==='set'){ball.vx=p.team===0?5.5:-5.5;ball.vy=-9.2;ball.lastTouch=p.team;p.pose='set';$('#callout').textContent='PERFECT SET';skill=Math.min(100,skill+15);}
 else{const block=players.some(q=>q.team!==p.team&&q.x>netX-56&&q.x<netX+56&&!q.onGround&&Math.abs(q.y-p.y)<35);const smash=Math.max(0,(profile.skill[0]-1)*.025);ball.vx=(p.team===0?1:-1)*(8.3+Math.random()*2.2+smash+(skill>=100&&abilityName==='POWER'?2.4:0));ball.vy=-(4.8+Math.random()*2.7);ball.lastTouch=p.team;ball.x+=p.team===0?12:-12;p.pose='hit';$('#callout').textContent=block?'BLOCK TOUCH!':'SPIKE!';skill=Math.min(100,skill+12);if(skill>=100&&abilityName==='POWER')skill=30;}
 playerAnim=0;updateHud();sparks.push({x:ball.x,y:ball.y,life:.35,color:type==='hit'?'#d8ff64':'#ffffff',count:type==='hit'?12:5});}
function useSpecial(){if(skill<100||scene!=='game')return;const user=players[0];skill=0;if(abilityName==='QUICK JUMP'){if(user.onGround){user.vy=-13;user.onGround=false;}$('#callout').textContent='QUICK JUMP!';}
 else if(abilityName==='IRON WALL'){user.glow=1;players.filter(p=>p.team===0).forEach(p=>{p.glow=1;if(Math.abs(ball.x-p.x)<100&&ball.vx<0){ball.vx=-ball.vx*.6;ball.vy-=3;}});$('#callout').textContent='IRON WALL!';}
 else if(abilityName==='PERFECT'){if(Math.hypot(ball.x-user.x,ball.y-(user.y-20))<160){contact(user,'pass');ball.vx=5.8;ball.vy=-9;$('#callout').textContent='PERFECT RECEIVE!';}else skill=100;}
 else if(abilityName==='ACE SERVE'){if(state==='serve'&&serving===0){serveType=0;serveBall();ball.vx=12.4;ball.vy=-7.3;$('#callout').textContent='ACE SERVE!';}else{skill=100;$('#callout').textContent='SPECIAL SERVE READY';}}
 else{if(state==='rally'&&ball.lastTouch!==0){ball.vx=10.5;ball.vy=-8;ball.lastTouch=0;$('#callout').textContent='POWER SHOT!';}else if(state==='serve')serveBall();else skill=100;}
 updateHud();}

