:root{
--ink:#f7f5eb;--muted:#8d95a7;--lime:#d8ff64;--cyan:#62e8ed;--bg:#101525;--panel:#1a2030;--line:#ffffff1a}
*{
box-sizing:border-box}
html,body{
margin:0;width:100%;height:100%;overflow:hidden;background:var(--bg);color:var(--ink);font-family:Manrope,system-ui,sans-serif;user-select:none;-webkit-user-select:none;-webkit-tap-highlight-color:transparent;touch-action:none}
button{
font:inherit;color:inherit;border:0;cursor:pointer;touch-action:manipulation}
#app{
position:relative;width:100%;height:100dvh;min-height:360px;overflow:hidden;background:radial-gradient(ellipse at 75% 30%,#222c42,#101525 66%)}
#game{
position:absolute;inset:0;width:100%;height:100%;image-rendering:pixelated;z-index:0}
.topbar{
position:absolute;z-index:5;left:4.2%;right:4.2%;top:24px;height:40px;display:flex;justify-content:space-between;align-items:center}
.brand{
display:flex;align-items:center;gap:11px;font-size:12px;letter-spacing:2.5px;font-weight:800}
.brand b{
color:var(--lime)}
.brand-mark{
display:grid;place-items:center;width:34px;height:34px;background:var(--lime);color:#18202a;font:900 13px 'Barlow Condensed';letter-spacing:-.4px;clip-path:polygon(0 0,100% 0,100% 75%,72% 100%,0 100%)}
.top-actions{
display:flex;align-items:center;gap:12px}
.offline{
font:10px 'DM Mono';color:#b4c1ce;letter-spacing:1px}
.offline:first-letter{
color:#8bf3ae}
.icon-btn{
width:34px;height:34px;border-radius:9px;background:#ffffff0b;border:1px solid var(--line);font-size:17px}
.screen{
position:absolute;inset:0;z-index:2;pointer-events:none}
.hero-copy{
position:absolute;left:10.5%;top:20%;pointer-events:auto}
.eyebrow{
font:10px 'DM Mono';letter-spacing:1.55px;color:#aab1bf}
.eyebrow span{
color:var(--lime);padding:0 6px}
h1{
font:900 clamp(58px,8vw,100px)/.79 'Barlow Condensed',sans-serif;letter-spacing:-2px;margin:21px 0 19px;text-transform:uppercase}
h1 em{
font-style:normal;color:var(--lime)}
.hero-copy p{
color:#a7adbb;font-size:13px;line-height:1.8;margin:0 0 23px}
.hero-buttons{
display:flex;gap:10px}
.primary,.secondary{
padding:14px 18px;font:800 11px 'DM Mono';letter-spacing:.8px;border-radius:5px}
.primary{
background:var(--lime);color:#161e28;min-width:170px;display:flex;justify-content:space-between;align-items:center}
.primary span{
font-size:14px}
.secondary{
background:#ffffff0b;border:1px solid #ffffff25;color:#eff2ed}
.keyboard-hint{
margin-top:22px;font:9px 'DM Mono';color:#8f98a9;letter-spacing:.4px}
.keyboard-hint span{
font-size:15px;margin-right:6px;color:#d4d7de}
.keyboard-hint i{
font-style:normal;color:var(--lime);padding:0 5px}
.menu-card{
position:absolute;right:10.2%;top:20%;width:min(310px,32vw);padding:18px 19px 13px;background:linear-gradient(140deg,#20293b,#171e2c);border:1px solid #ffffff18;border-radius:7px;box-shadow:0 20px 70px #0005;pointer-events:auto}
.card-head,.card-foot{
display:flex;justify-content:space-between;align-items:center;font:9px 'DM Mono';letter-spacing:1.3px;color:#a9b0bd}
.live-dot{
color:var(--lime);font-size:8px}
.menu-row{
width:100%;display:flex;align-items:center;gap:12px;text-align:left;padding:13px 0;background:transparent;border-bottom:1px solid #ffffff12}
.menu-row>span:nth-child(2){
flex:1}
.menu-row b{
display:block;font:800 12px 'Barlow Condensed';letter-spacing:.8px}
.menu-row small{
display:block;color:#9da5b3;font-size:9px;margin-top:3px}
.menu-row strong{
font:20px 'Barlow Condensed';color:#8a93a3}
.row-icon{
display:grid;place-items:center;width:31px;height:31px;border-radius:5px;font-size:15px;background:#ffffff0b}
.gold{
color:#ffd668}
.blue{
color:#78cfff}
.mint{
color:#87f0c3}
.pink{
color:#ff8bae}
.violet{
color:#bf9dff}
.card-foot{
padding-top:13px;font-size:8px}
.card-foot b{
color:#ecf0e9;font-weight:500;letter-spacing:.5px}
.season-tag{
position:absolute;left:10.5%;bottom:11%;border:1px solid #ffffff20;background:#ffffff08;padding:10px 13px;border-radius:4px;font:9px 'DM Mono';letter-spacing:.6px;color:#b1bac8}
.season-tag b{
color:#f8f2d4}
.season-tag span{
color:var(--lime);margin-left:7px}
.footer{
