 function awardXP(){while(profile.xp>=profile.level*220){profile.xp-=profile.level*220;profile.level++;profile.coins+=50;}}
 function showResult(win){result.innerHTML=`<div class="result-panel"><div class="modal-eyebrow">${mode==='tournament'?'NEON CUP • ROUND 1':'PIXEL SPORTS LEAGUE'}</div><h2 style="color:${win?'var(--lime)':'#ff8297'}">${win?'VICTORY!':'MATCH OVER'}</h2><div class="result-score">${String(points[0]).padStart(2,'0')} — ${String(points[1]).padStart(2,'0')}</div><p>${win?'A brilliant performance.':'Every loss is a lesson. Run it back.'}<br>+${win?(mode==='tournament'?250:100):3} coins earned</p><div class="modal-actions" style="justify-content:center"><button class="primary-action" id="againBtn">PLAY AGAIN</button><button id="resultMenu">MAIN MENU</button></div></div>`;result.classList.remove('hidden');$('#againBtn').onclick=()=>startGame(mode);$('#resultMenu').onclick=backMenu;}
 function act(type){if(scene!=='game'||paused||matchEnded)return;const user=players[0];if(type==='jump'){if(user.onGround){user.vy=-8.8*user.stats.jump*(skill>=100&&abilityName==='QUICK JUMP'?1.35:1);user.onGround=false;user.pose='jump';user.jumpTime=0;}return;}if(type==='serve'){if(state==='serve'&&serving===0){serveType=(serveType+1)%3;serveBall();}return;}if(state==='serve')return;user.pose=type==='pass'?'receive':type==='set'?'set':'hit';user.cool=.28;user.glow=.2;
- const dx=ball.x-user.x,dy=(user.y-18)-ball.y,dist=Math.hypot(dx,dy);let range=type==='hit'?83:type==='set'?65:70;if(!user.onGround)range+=13;if(dist<range&&ball.lastTouch!==0){if(type==='pass'){contact(user,'pass');}else if(type==='set'){contact(user,'set');}else if(type==='hit'){contact(user,'hit');}}
+ const dx=ball.x-user.x,dy=(user.y-18)-ball.y,dist=Math.hypot(dx,dy);let range=type==='hit'?83:type==='set'?65:70;if(!user.onGround)range+=13;if(dist<range){if(type==='pass'){contact(user,'pass');}else if(type==='set'){contact(user,'set');}else if(type==='hit'){contact(user,'hit');}}
 }
 function serveBall(){const user=players[0];state='rally';user.pose='serve';ball.x=user.x+20;ball.y=user.y-45;const power=serveType===1?10:serveType===2?9.3:8.6;ball.vx=power;ball.vy=serveType===2?-6.5:serveType===1?-2.5:-4.8;ball.spin=serveType===1?-.06:serveType===2?.1:0;ball.lastTouch=0;ball.trail=[];$('#callout').textContent=['POWER SERVE!','FLOAT SERVE!','JUMP SERVE!'][serveType];skill=Math.max(0,skill-18);updateHud();}
 function contact(p,type){if(ball.lastTouch===p.team&&type!=='hit')return;let perfect=Math.random()<p.stats.control*.7+(profile.skill[3]*.04);if(type==='pass'){ball.vx=(p.team===0?1:-1)*(2.1+jit(1.2));ball.vy=-7.8-(perfect?1.2:0);ball.x+=p.team===0?10:-10;ball.lastTouch=p.team;p.pose='receive';$('#callout').textContent=perfect?'CLEAN DIG!':'RECEIVED';skill=Math.min(100,skill+18);}
  else if(type==='set'){ball.vx=p.team===0?5.5:-5.5;ball.vy=-9.2;ball.lastTouch=p.team;p.pose='set';$('#callout').textContent='PERFECT SET';skill=Math.min(100,skill+15);}

